// Emit one item per uploaded file so Extract from File can process each PDF independently.
const item = $input.first();
const bin = item.binary || {};
const out = [];
for (const key of Object.keys(bin)) {
  out.push({ json: { source_file: bin[key].fileName || key }, binary: { file: bin[key] } });
}
return out;

// Combine text extracted from ALL uploaded files with any body text into one source.
const wb = $('Content Intake Webhook').item.json.body || {};
const bodyText = (wb.source_text || '').toString().trim();
const fileChunks = $input.all()
  .map((i) => (i.json.text || '').toString().trim())
  .filter(Boolean);
const parts = [];
if (bodyText) parts.push(bodyText);
for (const c of fileChunks) parts.push(c);
const source_text = parts.join('\n\n---\n\n');
return [{
  json: {
    source_text,
    user_instruction: (wb.user_prompt || '').toString().trim(),
    input_type: 'mixed',
    output_types: Array.isArray(wb.output_types) ? wb.output_types : [],
  },
}];

const src = ($json.source_text || '').toString().trim();
const types = Array.isArray($json.output_types) ? $json.output_types : [];
let error_message = "";
if (!src) {
  error_message = "No source content could be read. Provide non-empty source_text and/or one or more readable PDF files. DOCX extraction is not supported yet.";
} else if (types.length === 0) {
  error_message = "output_types is empty or missing. Provide at least one of: exec_summary, public_advisory, linkedin_post, twitter_thread.";
}
return {
  json: {
    source_text: src,
    user_instruction: ($json.user_instruction || '').toString().trim(),
    input_type: $json.input_type,
    output_types: types,
    is_valid: error_message === "",
    error_message,
  },
};

const raw = $('Validate Source & Types').item.json;
const out = ($json.output || '').toString();
const idx = out.lastIndexOf('CORRECTIONS:');
let corrected = out;
let corrections = '[]';
if (idx !== -1) {
  corrected = out.slice(0, idx).replace(/\s+$/, '');
  corrections = out.slice(idx + 'CORRECTIONS:'.length).trim();
}
const finalText = (corrected || '').trim() || raw.source_text;
return {
  json: {
    source_text: finalText,
    source_text_raw: raw.source_text,
    corrections,
    user_instruction: raw.user_instruction || '',
    input_type: raw.input_type,
    output_types: raw.output_types,
  },
};

const item = $input.first().json;
const types = Array.isArray(item.output_types) ? item.output_types : [];
return types.map((t) => ({
  json: {
    source_text: item.source_text,
    user_instruction: item.user_instruction || '',
    output_type: t,
  },
}));

// Builds the prompt for each generation attempt. On the first pass the input comes from
// Template Resolver (system_prompt/user_prompt). On a retry it comes from Derive Verification
// Result, carrying the auditor's feedback + previous output so the agent can fix unsupported claims.
const j = $json;
const isRetry = typeof j.verification_result === 'string' && j.verification_result.trim() !== '' && j.is_verified === false;
const base_system_prompt = j.base_system_prompt || j.system_prompt || '';
const base_user_prompt = j.base_user_prompt || j.user_prompt || '';
const attempt = isRetry ? (Number(j.attempt) || 1) + 1 : 1;
let system_prompt = base_system_prompt;
if (isRetry) {
  system_prompt = base_system_prompt +
    "\n\n=== REVISION REQUIRED (attempt " + attempt + ") ===\n" +
    "A separate fact-checking auditor reviewed your previous output and found statements NOT supported by the SOURCE CONTENT. You MUST remove or correct EVERY flagged item, then regenerate the COMPLETE output while keeping all original format, tone, and length constraints. Do not introduce any new unsupported facts. If a detail is not in the source, omit it.\n\n" +
    "YOUR PREVIOUS OUTPUT:\n" + (j.generated_text || '') + "\n\n" +
    "AUDITOR FEEDBACK (unsupported claims to fix):\n" + (j.verification_result || '');
}
return {
  json: {
    source_text: j.source_text,
    output_type: j.output_type,
    output_label: j.output_label,
    base_system_prompt,
    base_user_prompt,
    system_prompt,
    user_prompt: base_user_prompt,
    attempt,
  },
};

const s = $('Build Gen Prompt').item.json;
return {
  json: {
    source_text: s.source_text,
    output_type: s.output_type,
    output_label: s.output_label,
    base_system_prompt: s.base_system_prompt,
    base_user_prompt: s.base_user_prompt,
    attempt: s.attempt,
    generated_text: ($json.output || '').toString().trim(),
  },
};

