const s = $('Store Generated Text').item.json;
const v = ($json.output || '').toString().trim();
return {
  json: {
    source_text: s.source_text,
    output_type: s.output_type,
    output_label: s.output_label,
    base_system_prompt: s.base_system_prompt,
    base_user_prompt: s.base_user_prompt,
    attempt: s.attempt,
    generated_text: s.generated_text,
    verification_result: v,
    is_verified: v.startsWith("VERIFIED"),
  },
};

const norm = $('Apply Normalization').first().json;
const outputs = $input.all().map((i) => ({
  output_type: i.json.output_type,
  output_label: i.json.output_label,
  generated_text: i.json.generated_text,
  verification_result: i.json.verification_result,
  is_verified: i.json.is_verified,
}));
return [{ json: { outputs, corrections: norm.corrections, source_text_raw: norm.source_text_raw } }];

return {
  json: {
    output_type: $json.output_type,
    output_label: "Unsupported",
    generated_text: "",
    verification_result: "ERROR: Unrecognized output_type \"" + $json.output_type + "\". Supported values: exec_summary, public_advisory, linkedin_post, twitter_thread.",
    is_verified: false,
  },
};

const wb = $json.body || {};
const src = (wb.source_text || '').toString().trim();
return {
  json: {
    source_text: src,
    user_instruction: (wb.user_prompt || '').toString().trim(),
    input_type: wb.input_type,
    output_types: Array.isArray(wb.output_types) ? wb.output_types : [],
  },
};
